import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('114.', 1060, own='lote_4.jsonl')
def H(code, d, q, right, wrong, e):
    return B.hand(code, d, q, right, wrong, e)

# ===== 114.39 Level I, Novice Mid to Novice High =====
H('39.c.1.A',1,"In a first-year language class, a partner asks you what you do after school. This is a question about:","everyday life",["quantum physics","ancient law","tax forms"],"Level I students talk about familiar, everyday topics.")
H('39.c.1.A',2,"Which pair of tasks shows two-way communication at Level I?","asking a question and giving an answer",["reading silently and not responding","copying a list of words","memorizing a poem alone"],"Interpersonal communication goes both ways.")
H('39.c.1.B',2,"Which sentence frame fits sharing a personal preference in a new language?","I like ___ because it is fun.",["The treaty was signed in ___.","The sum of the angles is ___.","The formula for area is ___."],"Preferences are expressed with simple frames.")
H('39.c.1.B',2,"Two classmates trade opinions about school lunch in the target language. This exchange is:","interpersonal communication",["presentational reading only","silent copying","a written test only"],"Exchanging opinions is two-way communication.")
H('39.c.1.C',2,"Which statement tells someone what they must do?","You must wear a helmet.",["I like bicycles.","The bike is red.","It is sunny."],"Must expresses necessity.")
H('39.c.1.C',2,"At Level I, a student tells a friend what he should do before a test. This uses language of:","advice and obligation",["weather reports","historical dates","number facts"],"Should and must express advice and obligation.")
H('39.c.1.D',2,"Which sentence makes a polite request?","Could you pass me the book, please?",["The book is heavy.","I read yesterday.","Books are made of paper."],"Requests use polite forms.")
H('39.c.1.D',3,"A student says, We could go to the park or to the library. This offers:","alternatives",["a refusal","a command","a story"],"Alternatives give options.")
H('39.c.1.E',2,"In many languages a speaker uses a formal way of addressing a teacher. This is an example of choosing the right:","register",["spelling","alphabet","map scale"],"Register fits the audience and setting.")
H('39.c.1.E',3,"A culturally appropriate gesture when greeting varies by culture. A learner should:","observe and use the gestures that fit the culture",["use only the learner's own gestures","ignore all gestures","use a gesture from a random culture"],"Gestures are part of culturally appropriate speech.")
H('39.c.1.F',2,"A pen pal writes a note to a teacher in the target language. The student should choose:","a polite and respectful style",["slang words","insults","random letters"],"Written style also depends on the reader.")
H('39.c.1.F',3,"Which written greeting best fits a note to a younger cousin?","a friendly and informal opening",["a legal heading","a technical title","a formal title and signature block"],"Informal writing suits family.")
H('39.c.2.A',2,"A learner reads a menu from a restaurant in another country. This is an example of using:","authentic print material",["a made-up worksheet","a blank page","a cartoon without words"],"Authentic materials are made by speakers for real use.")
H('39.c.2.A',3,"Which source counts as authentic audiovisual material?","a short video made for native speakers",["a silent drawing","a spelling list","a classroom rule chart"],"Authentic materials come from real communication.")
H('39.c.2.B',2,"After watching a short clip, a student lists key words and details. This shows skill in:","interpretive listening and viewing",["spelling aloud","presentational writing","map reading"],"Interpretive skills understand what others produce.")
H('39.c.2.B',2,"Which detail would a novice learner pick from a short story?","the name of a character and where the story happens",["the author's hidden agenda","a philosophical theory","a tax statement"],"Key details are concrete and basic.")
H('39.c.2.C',3,"A learner meets an unfamiliar word in a text with pictures. The best strategy is to:","use pictures and nearby words to infer meaning",["skip the whole text","guess a random meaning","stop reading"],"Context helps in highly contextualized materials.")
H('39.c.2.C',3,"Highly contextualized material is easier to understand because:","visual and situational clues support the words",["there is no text","it has only numbers","it avoids pictures"],"Context clues support comprehension.")
H('39.c.2.D',2,"A learner sees a photo of a family meal in a video from another country. What does the learner identify?","a cultural practice",["a math formula","a chemical symbol","a map legend"],"Practices are customs seen in everyday life.")
H('39.c.2.D',3,"Watching a festival video helps a learner notice:","customs and traditions of the culture",["only the language alphabet","the cost of the video","nothing at all"],"Authentic media show cultural practices.")
H('39.c.3.A',2,"A student says, I prefer tea, and explains with one reason. This is:","stating and supporting a preference",["asking directions","describing weather","reciting numbers"],"Preferences include simple support.")
H('39.c.3.A',3,"Which written sentence states and supports an opinion at Level I?","I like soccer because it is exciting.",["Soccer.","The ball.","Soccer game ball field."],"A because clause gives support.")
H('39.c.3.B',2,"Describing a friend with words and short phrases is an example of:","presentational speaking or writing",["interpersonal chatting only","silent viewing","tax filing"],"Presentational communication is one-way.")
H('39.c.3.B',3,"At the novice level, a description may use a mixture of:","words, phrases and simple sentences",["only long paragraphs","only symbols","only single sounds"],"Novice learners combine words and phrases.")

# ===== 114.40 Level II, Novice High to Intermediate Low =====
H('40.c.1.A',2,"In Level II a student not only answers a question but adds a detail. This is:","simple elaboration",["silence","copying","avoidance"],"Elaboration adds information.")
H('40.c.1.A',3,"Which response shows simple elaboration to the question, What did you do on the weekend?","I went to the lake and swam with my cousins.",["Yes.","Lake.","No answer."],"Elaboration gives detail.")
H('40.c.1.B',3,"At Level II, a student gives an opinion about a movie and adds supporting statements. This builds:","conversational depth",["only vocabulary lists","only rote spelling","silent viewing"],"Supporting statements deepen conversation.")
H('40.c.1.B',3,"Which pair of statements expresses an opinion with support?","I like the film. The music is exciting.",["The film.","Yes. Film. Maybe.","Movie, movie."],"Support follows the opinion.")
H('40.c.1.C',3,"A student says, You should sleep early because the test is tomorrow. This tells someone what to do with:","a supporting reason",["a weather report","a greeting only","a request for money"],"Reasons support advice.")
H('40.c.1.C',3,"Which sentence uses necessity with a reason?","We must clean the room because guests are coming.",["The room.","We clean.","Guests."],"Must plus because gives obligation and reason.")
H('40.c.1.D',3,"Planning a class party includes making requests, offering alternatives and giving:","simple supporting statements",["random facts","unrelated stories","only numbers"],"Plans are supported by short statements.")
H('40.c.1.D',3,"A student suggests, We could meet at noon or at one o'clock; noon is better because it is cooler. This offers:","alternatives with a reason",["a command only","a refusal only","a joke"],"The speaker gives options and a reason.")
H('40.c.1.E',3,"Interacting and reacting in conversation means the student:","responds to what the other person says",["recites memorized lines only","reads silently","writes only"],"Reaction builds real conversation.")
H('40.c.1.E',3,"A culturally appropriate reaction to good news includes:","an expression that shows appropriate enthusiasm",["staring silently","leaving abruptly","changing the subject"],"Reactions follow cultural norms.")
H('40.c.1.F',3,"Reacting in writing to a friend's email by answering questions and adding comments shows:","interactive written communication",["only copying","only drawing","only listening"],"Written interaction responds to messages.")
H('40.c.1.F',3,"Which closing is culturally appropriate in a note to a teacher?","a respectful closing with thanks",["a rude remark","a joke only","no closing and no name"],"Style fits the reader.")
H('40.c.2.A',3,"Authentic materials at Level II include:","a news clip or a short article made for native speakers",["a worksheet written only for learners","a blank map","a scrambled alphabet"],"Authentic items are real communication.")
H('40.c.2.A',3,"A learner watches an audiovisual advertisement from another country. This helps the learner:","see how language and culture work together",["avoid the target language","skip the culture","ignore the images"],"Media connect language and culture.")
H('40.c.2.B',3,"A theme is:","the central message of a text",["the title page","a single word","the author's address"],"Themes are central ideas.")
H('40.c.2.B',3,"Which task shows identifying the main idea and supporting details?","stating what a story is mostly about and naming two events",["copying the first sentence","counting words","skipping the story"],"Main ideas and details show comprehension.")
H('40.c.2.C',3,"To infer the meaning of an unfamiliar phrase in a highly contextualized video, a learner can:","use images, gestures and context",["stop watching","guess at random","ignore the video"],"Context supports inference.")
H('40.c.2.C',3,"Inference means:","using clues to figure out what is not directly stated",["ignoring clues","memorizing a definition","copying words"],"Inference is based on clues.")
H('40.c.2.D',3,"From a short documentary, a learner identifies a family tradition. This shows ability to:","identify cultural practices",["identify chemical formulas","identify geologic layers","identify tax codes"],"Practices are visible in authentic media.")
H('40.c.2.D',3,"Which feature of a video can reveal a cultural practice?","how people greet and eat together",["the length of the credits","the file size","the brand of the camera"],"Daily routines reveal practices.")
H('40.c.3.A',3,"At Level II, a student gives an opinion in a short speech and adds supporting statements. This is:","presentational communication",["silent reading only","two-way chatting only","dictionary work"],"Presentations are one-way.")
H('40.c.3.A',3,"Which written paragraph expresses an opinion with support?","I prefer winter because I can ski, and the snow is beautiful.",["Winter.","I ski.","Snow."],"Support follows the opinion.")
H('40.c.3.B',3,"Describing a place with a series of sequenced sentences means:","putting details in a logical order",["listing random words","reading backward","avoiding detail"],"Sequence organizes a description.")
H('40.c.3.B',3,"Which description is organized in sequence?","First we arrived, then we ate, and finally we walked home.",["Walked home we then arrived.","Ate and home first.","Home."],"Sequence words order events.")
B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'batches', 'lote_4.jsonl'))
